foreach($dependency in @('NX-AUTH-001','NX-MEDIA-001','NX-CHAIN-001','NX-CHAIN-002')){$record=[regex]::Match($b0,('(?ms)^  - task_id:\s*'+[regex]::Escape($dependency)+'\s*\r?\n(.*?)(?=^  - task_id:|\z)'));Assert-Adult ($record.Success-and$record.Groups[1].Value-match'(?m)^\s+status:\s*done\s*$') "Dependency not done: $dependency"}
foreach($dependency in @('NX-ECON-P01','NX-MOD-P01')){$record=[regex]::Match($b1,('(?ms)^  - task_id:\s*'+[regex]::Escape($dependency)+'\s*\r?\n(.*?)(?=^  - task_id:|\z)'));Assert-Adult ($record.Success-and$record.Groups[1].Value-match'(?m)^\s+status:\s*done\s*$') "Dependency not done: $dependency"}
$active=@([regex]::Matches($b1,'(?ms)^  - task_id:\s*(\S+)\s*\r?\n(.*?)(?=^  - task_id:|\z)')|Where-Object{$_.Groups[2].Value-match'(?m)^\s+record_kind:\s*task_packet\s*$'-and$_.Groups[2].Value-match'(?m)^\s+status:\s*(in_progress|review)\s*$'}|ForEach-Object{$_.Groups[1].Value});Assert-Adult ($active.Count-eq1-and$active[0]-eq'NX-ADULT-P01') 'WIP one violated'
