Assert-Adult (@($contract.entitlement.offers).Count-eq7-and[bool]$contract.entitlement.freeDiscoveryStillAgeGated-and-not[bool]$contract.entitlement.freeDiscoveryVisibleOutsidePrive-and[bool]$contract.entitlement.encryptedPerAssetKeyRequired-and-not[bool]$contract.entitlement.viewerGraphPublic-and-not[bool]$contract.entitlement.exactEntitlementOnChain-and[bool]$contract.entitlement.accessRechecksCurrentAgeConsentRightsTerritoryAndTakedown) 'Entitlement gate'
